// Theme packs. One pack = one look in light AND dark. Never add a light-only or
// dark-only entry: pair it or drop it. The first entry is the app's default.
// CSS lives in globals.css (generated by shipyard theme-packs.mjs css); this file is the
// list the picker shows and the ids the pre-paint script accepts.

export type PackTokens = {
  bg: string; surface: string; text: string; muted: string;
  border: string; accent: string; onAccent: string;
  extra?: Record<string, string>; // extra CSS variables, e.g. "--shadow-2"
};
export type ThemePack = {
  id: string;
  label: string;
  description?: string;
  preview: string; // /themes/<id>.png, a screenshot showing light and dark halves
  tokens: { light: PackTokens; dark: PackTokens };
};
export type ModeChoice = "light" | "dark" | "system";

export const PACK_KEY = "theme-pack";
export const MODE_KEY = "theme";

export const PACKS: ThemePack[] = [
  {
    id: "classic",
    label: "Classic",
    preview: "/themes/classic.png",
    tokens: {
      light: { bg: "#fafaf9", surface: "#ffffff", text: "#1c1917", muted: "#57534e", border: "#e7e5e4", accent: "#0f766e", onAccent: "#ffffff" },
      dark: { bg: "#0c0a09", surface: "#1c1917", text: "#f5f5f4", muted: "#a8a29e", border: "#292524", accent: "#2dd4bf", onAccent: "#042f2e" },
    },
  },
];

export const DEFAULT_PACK = PACKS[0].id;

export function getPack(id: string | null | undefined): ThemePack {
  return PACKS.find((p) => p.id === id) ?? PACKS[0];
}

/** Same rule as the pre-paint script, so the page and the picker never disagree. */
export function applyPack(id: string, mode: ModeChoice) {
  const d = document.documentElement;
  const dark = mode === "dark" || (mode === "system" && matchMedia("(prefers-color-scheme: dark)").matches);
  d.setAttribute("data-pack", getPack(id).id);
  d.setAttribute("data-theme", dark ? "dark" : "light");
}
